 ax.axvline(0,color='#666',lw=.8);ax.grid(axis='x',alpha=.18);ax.set_title(title,fontsize=12);ax.set_yticks(np.arange(len(z)));ax.set_yticklabels(order);ax.set_xlabel('Logistic selector: change in test F1 (percentage points)');ax.spines['top'].set_visible(False);ax.spines['right'].set_visible(False)
